const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{spawn}=require('node:child_process');
const {rpc,toolCall}=require('../mcp-server.cjs'),{validate}=require('../map-core.cjs');
const project=()=>JSON.parse(fs.readFileSync(path.join(__dirname,'../../地图/晴日港区集装箱争夺.along-map.json'),'utf8'));
test('MCP can share a running editor and deliver generated map across processes',async()=>{const {start}=require('../mcp-server.cjs'),server=start(18766);await new Promise(resolve=>server.once('listening',resolve));try{const proc=spawn(process.execPath,[path.join(__dirname,'../mcp-server.cjs')],{env:{...process.env,ALONG_EDITOR_PORT:'18766'},stdio:['pipe','pipe','pipe']});let output='',err='';proc.stdout.on('data',c=>output+=c);proc.stderr.on('data',c=>err+=c);const guidanceToken=toolCall('read_guidance').guidanceToken;for(const req of [{id:1,method:'tools/call',params:{name:'read_guidance',arguments:{}}},{id:2,method:'tools/call',params:{name:'create_map',arguments:{guidanceToken,project:project()}}}])proc.stdin.write(JSON.stringify({jsonrpc:'2.0',...req})+'\n');proc.stdin.end();assert.equal(await new Promise(resolve=>proc.on('close',resolve)),0,err);const result=JSON.parse(output.trim().split('\n')[1]).result;assert.ok(!result.isError,JSON.stringify(result));const saved=JSON.parse(result.content[0].text),events=await (await fetch('http://127.0.0.1:18766/api/events?after='+(saved.revision-1))).json();assert.equal(events[0].type,'map');assert.equal(events[0].project.objects.length,79);}finally{await new Promise(resolve=>server.close(resolve));}});
test('MCP exposes guidance and real generation tools',()=>{assert.equal(rpc({method:'initialize'}).serverInfo.name,'along-map-editor');assert.equal(rpc({method:'tools/list'}).tools.length,5);assert.throws(()=>toolCall('create_map',{project:project()}),/read_guidance/);const result=toolCall('read_guidance');assert.equal(result.guidanceToken.length,64);assert.match(result.instructions,/空气墙/);assert.match(result.instructions,/人物/);});
test('port passes; missing walls, bad spawn, bad transform and wrong weather fail',()=>{assert.deepEqual(validate(project()),[]);const p=project();p.objects=p.objects.filter(o=>!o.airwall);assert.equal(validate(p).filter(e=>e.includes('空气墙')).length,4);const q=project();q.objects.find(o=>o.role==='spawn').position=[500,0,0];assert.ok(validate(q).some(e=>e.includes('出生点')));const r=project();r.objects[0].scale=[0,1,1];assert.ok(validate(r).some(e=>e.includes('变换')));const s=project();s.weather='rain';assert.ok(validate(s).some(e=>e.includes('sunny')));});
test('asset write rejects missing slots and system access',()=>{const guidanceToken=toolCall('read_guidance').guidanceToken;const html=code=>`<script id="along-asset" type="application/json">{"id":"ai.test-invalid","name":"测试","units":"m","visualStyle":"realistic","styleReference":"沿线港区"}</script><script id="along-factory" type="text/plain">${code}</script>`;assert.throws(()=>toolCall('create_asset',{guidanceToken,html:html('return fetch("x")')}),/不允许/);assert.throws(()=>toolCall('create_asset',{guidanceToken,html:html('return new ctx.THREE.Group()')}),/碰撞和材质槽/);});
test('stdio JSON-RPC initialize, tool discovery and invalid map response',async()=>{const proc=spawn(process.execPath,[path.join(__dirname,'../mcp-server.cjs')],{env:{...process.env,ALONG_EDITOR_PORT:'18767'},stdio:['pipe','pipe','pipe']});let output='',err='';proc.stdout.on('data',c=>output+=c);proc.stderr.on('data',c=>err+=c);for(const req of [{id:1,method:'initialize',params:{}},{id:2,method:'tools/list'},{id:3,method:'tools/call',params:{name:'validate_map',arguments:{project:{objects:[]}}}}])proc.stdin.write(JSON.stringify({jsonrpc:'2.0',...req})+'\n');proc.stdin.end();const code=await new Promise(resolve=>proc.on('close',resolve));assert.equal(code,0,err);const lines=output.trim().split('\n').map(JSON.parse);assert.equal(lines.length,3);assert.equal(lines[0].result.serverInfo.name,'along-map-editor');assert.equal(lines[1].result.tools.length,5);assert.equal(JSON.parse(lines[2].result.content[0].text).valid,false);});
